{
  "description": "The creature is a large, quadrupedal, bear-like animal shown in right-facing profile standing on a pale ground with small patches of grass. Its body is covered in dense, shaggy brown fur that is darker on the legs and back and paler tan on the muzzle, lower neck, chest and belly. Multiple large, glossy, dark reddish-brown to black chitinous plates with fine segmented lines and bright reflections are set into the fur on the back, sides, neck, rump and outer legs. A single long, smooth, glossy dark horn curves up and forward from the forehead. The head is broad with a bear-like muzzle and nose, small dark eyes, and small rounded ears. It stands on four thick, clawed limbs and no tail or wings are visible.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad bear-like head with dense brown fur, a lighter tan muzzle, a large black nose at the tip, a small dark brown eye on the side, and a slightly open mouth showing the lower jaw line",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one single, thick, smooth and highly glossy dark brown-black horn, strongly recurved upward and forward to a sharp point, with two small thorn-like projections on the inner concave edge and a rounded base set in fur",
      "where": "emerging from the midline of the forehead between the eyes and ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred ears with brown fur, slightly lighter inside",
      "where": "on top of the head just behind the base of the horn, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, heavily furred limbs with long shaggy brown fur, darker toward the paws",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the hips, supporting the body vertically"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with thick fur and five long, curved, light tan claws visible on each paw",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "plates",
      "looks_like": "about ten large, hard-looking, glossy dark mahogany plates with irregular crack-like segmentation and white specular highlights; shapes range from small oval on the back to large rectangular with rounded corners on the mid-flank, and smaller curved plates on the neck, rump and outer sides of all four legs",
      "where": "distributed on the dorsal midline (two small plates), left lateral torso (one very large plate), shoulder/neck (two plates), rump/hip (one large plate), and lateral surfaces of the fore and hind legs"
    },
    {
      "part": "markings",
      "looks_like": "a horizontal row of six small, vertically oval, black pit-like openings with thin pale rims, set in a line",
      "where": "in the pale tan fur on the lower flank, just below the large lateral plate and above the belly, between the fore and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 0
}
